import React from 'react';
import './Hero.css';

export const Hero = () => {
  return (
    <section className="hero-section">

      {/* Layer 0 — Sky background image */}
      <img
        src={process.env.PUBLIC_URL + '/bg%20hero.webp'}
        alt=""
        className="hero-bg"
        aria-hidden="true"
      />

      {/* Layer 1 — Vignette / dark overlay (6-stop gradient matching reference)
          Very dark at top → clears mid-section → darkens again at bottom */}
      <div className="hero-vignette" aria-hidden="true" />

      {/* Layer 2 — Text & CTA + Dashboard card */}
      <div className="nl-hero-content">
        <h1 className="nl-hero-heading">
          The intelligent travel companion<br />
          for <em>every journey you take.</em>
        </h1>
        <p className="nl-hero-subtitle">
          Your journey, our priority. Powered by AI, tailored for you.
        </p>
        <div className="nl-cta-row">
          <button id="nl-try-beta" className="nl-btn-hero-white">Join the Beta</button>
        </div>

        {/* Dashboard card — sits inside content block, z-index inherited */}
        <div className="hero-dashboard-wrapper">
          <img
            src={process.env.PUBLIC_URL + '/hero%20bg%20new.webp'}
            alt="Dishastra app dashboard"
            className="hero-dashboard"
          />
        </div>
      </div>

      {/* Layer 4 — Hills foreground anchored to bottom
          Has its own internal gradient fade that merges into the next section */}
      <div className="hero-hills-wrapper">
        <img
          src={process.env.PUBLIC_URL + '/image.webp'}
          alt=""
          className="hero-hills"
          aria-hidden="true"
        />
        {/* Internal hills overlay: transparent at top → solid #040404 at very bottom */}
        <div className="hero-hills-fade" aria-hidden="true" />
      </div>

    </section>
  );
};
